  for change in select value from jsonb_array_elements($idecan_review_batch$[{"candidate":"450567393cf35e12f428a93fa27d27b3c045dfcb51b74b39a29fda17d8cbf025","expected_status":"under_review","expected_payload":{"raw_text":"1. Para a socióloga Paula Poncioni, pesquisadora da UFRJ\n(Universidade Federal do Rio de Janeiro), falhas de formação\nsão um dos fatores que explicam o desempenho policial.\n(linhas 16 e 17)\nO ouvidor da Polícia do Estado de São Paulo, Elizeu Soares\nLopes, diz considerar a formação da polícia muito boa, mas\nressalva que é preciso reforço. (linhas 24 e 25)\nPela leitura dos períodos acima, é correto concluir que\nA) há mais de uma pesquisadora na UFRJ e mais de um ouvidor\nna Polícia do Estado de São Paulo.\nB) no primeiro período, o tom é impressionista; no segundo,\nargumentativo.\nC) no primeiro período, há um fato narrado; no segundo, uma\nopinião defendida.\nD) o primeiro período, diferentemente do segundo, se constrói\ncom apontamento de causalidade.\nE) ambos os períodos se constroem por mecanismos antitéticos.","item_number":1,"source_pages":[2],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"1. Para a socióloga Paula Poncioni, pesquisadora da UFRJ\n(Universidade Federal do Rio de Janeiro), falhas de formação\nsão um dos fatores que explicam o desempenho policial.\n(linhas 16 e 17)\nO ouvidor da Polícia do Estado de São Paulo, Elizeu Soares\nLopes, diz considerar a formação da polícia muito boa, mas\nressalva que é preciso reforço. (linhas 24 e 25)\nPela leitura dos períodos acima, é correto concluir que\nA) há mais de uma pesquisadora na UFRJ e mais de um ouvidor\nna Polícia do Estado de São Paulo.\nB) no primeiro período, o tom é impressionista; no segundo,\nargumentativo.\nC) no primeiro período, há um fato narrado; no segundo, uma\nopinião defendida.\nD) o primeiro período, diferentemente do segundo, se constrói\ncom apontamento de causalidade.\nE) ambos os períodos se constroem por mecanismos antitéticos.","item_number":1,"source_pages":[2],"answer_in_official_document":"D","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"primeiro_parecer_pedagogico_com_publicacao_retida","reviewed_at":"2026-10-23T00:16:25Z","publication_approved":false,"context_complete":true,"visual_checked":true,"answer_verified":false,"pedagogical_check_complete":true,"legal_review_applicability":"nao_juridica","question_format":"multiple_choice","observed_topic":"Relações de causa e comparação de enunciados","observed_style":"Comparação de trechos do texto","explanation":"O primeiro período relaciona as falhas de formação ao desempenho policial e apresenta causalidade. O segundo registra a avaliação do ouvidor e a ressalva sobre reforço da formação. A alternativa D é compatível com essa diferença; isso não resolve o cabeçalho conflitante do gabarito de Inspetor.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"title":"Gabarito PC-CE — seção do respectivo cargo, Tipo B","url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","page":3,"verified":true,"checked_at":"2026-10-23T00:16:25Z","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","scope":"Documento e divergência do cabeçalho conferidos; resposta definitiva NÃO certificada"}],"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[2],"checked_at":"2026-10-23T00:16:25Z","pdf_visual_checked":true},"restored_context":{"support_passage":{"title":"Policiais assassinados no Brasil são negros na maioria","source_page":2,"credit":"Anelise Gonçalves, Marcelo Azevedo, Matheus Rocha, Paulo Eduardo Dias, Paulo Ricardo Martins e Vitor Soares. Folha de S.Paulo, 1º ago.2021.","lines":[{"number":1,"text":"No ano passado, 194 policiais foram assassinados no país, e 63% deles eram negros."},{"number":2,"text":"Para Samira Bueno, diretora-executiva do Fórum Brasileiro de Segurança Pública, a ideia de que policiais são heróis os"},{"number":3,"text":"deixa mais vulneráveis e contribui para o aumento no número de mortes."},{"number":4,"text":"“Eles tendem a reagir a qualquer situação por causa da ideia fantasiosa de que se é policial 24 horas por dia.”"},{"number":5,"text":"Mesmo em um ano com menor circulação de pessoas nas ruas, devido à pandemia, a quantidade de mortes de agentes"},{"number":6,"text":"de segurança pública cresceu 13% no país em relação a 2019."},{"number":7,"text":"Segundo o último anuário do Fórum Brasileiro de Segurança Pública, 7 a cada 10 mortes ocorreram fora do horário de"},{"number":8,"text":"trabalho dos policiais. Eles foram mortos em passeios, no trajeto de ida e volta da corporação ou quando faziam serviços paralelos,"},{"number":9,"text":"os ‘‘bicos’’, ilegais, mas realizados para complementar a renda."},{"number":10,"text":"A reportagem ouviu um policial militar que atua no Rio de Janeiro há 20 anos."},{"number":11,"text":"“Entrei por querer estabilidade, depois me apaixonei pela profissão”, diz ele, que pediu para não ser identificado."},{"number":12,"text":"O PM criticou o treinamento dado pela corporação: ‘‘O policial acaba aprendendo na rua’’, diz. E reclamou da falta de"},{"number":13,"text":"apoio jurídico, do Estado, da sociedade e dos superiores ao trabalho do policial."},{"number":14,"text":"Sobre o fato de negros serem as maiores vítimas da violência, ele descarta preconceito. Na sua visão, ocorre porque a"},{"number":15,"text":"maioria da população é de pessoas negras. “Policial não escolhe criminoso.”"},{"number":16,"text":"Para a socióloga Paula Poncioni, pesquisadora da UFRJ (Universidade Federal do Rio de Janeiro), falhas de formação"},{"number":17,"text":"são um dos fatores que explicam o desempenho policial. “Muitas vezes, há um currículo ajustado à matriz nacional, mas não há"},{"number":18,"text":"professores qualificados, as aulas são recheadas de preconceitos”, diz a autora de “Tornar-se Policial’’ (Editora Appris)."},{"number":19,"text":"A letalidade policial, para Poncioni, decorre de uma sociedade “muito violenta e muito hierárquica”. Ela afirma que a"},{"number":20,"text":"polícia mata mais no Brasil por representar o pensamento geral da sociedade, refletido na composição dos governos que"},{"number":21,"text":"administram as polícias."},{"number":22,"text":"“A formação profissional está eivada de crenças, valores e preconceitos de um sistema de representação sobre o que é"},{"number":23,"text":"polícia, o que é criminoso, o que é mulher, o que é o menor e o que é o negro”, aponta."},{"number":24,"text":"O ouvidor da Polícia do Estado de São Paulo, Elizeu Soares Lopes, diz considerar a formação da polícia muito boa, mas"},{"number":25,"text":"ressalva que é preciso reforço. “Insistimos na necessidade de ações formativas em direitos humanos. A qualificação e a"},{"number":26,"text":"requalificação permanente dos quadros da polícia são fundamentais, seja ela civil, militar ou técnico-científica.”"},{"number":27,"text":"Hoje, a matriz curricular que define as regras para a formação de policiais no Brasil está em sua segunda versão, editada"},{"number":28,"text":"em 2014, no governo Dilma Rousseff (PT). Nela, o Ministério da Justiça orienta as ações formativas dos profissionais. Na grade"},{"number":29,"text":"dos cursos há, por exemplo, determinação para que os aspirantes tenham acesso a um módulo de 14 horas de aulas sobre"},{"number":30,"text":"diversidade étnico-racial."},{"number":31,"text":"Procurado, o Ministério da Justiça não respondeu."}],"historical_text":true},"reference_segments":[],"original_underline_segments":[],"typography_note":"Termos identificados visualmente na página; a extração original não foi reescrita.","original_exam_required_for_symbolic_notation":false}}}},{"candidate":"be36723a278818d4416765275b38538757a804e7be8f9135e8a90afe34d84dec","expected_status":"under_review","expected_payload":{"raw_text":"2. Em relação às corretas inferências da leitura do texto, analise as\nafirmativas a seguir:\nI. Em 2020, ocorreu uma contradição entre o cenário de pandemia\ne a escalada da morte de agentes policiais.\nII. Uma das ideias apresentadas é que não há preconceito no país,\nem que o argumento para comprová-lo é que morrem mais\nnegros por serem maior percentual da população.\nIII. No contexto social brasileiro, a morte dos policiais ocorre por\nações provocadas por elementos externos a eles.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta.","item_number":2,"source_pages":[2],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"2. Em relação às corretas inferências da leitura do texto, analise as\nafirmativas a seguir:\nI. Em 2020, ocorreu uma contradição entre o cenário de pandemia\ne a escalada da morte de agentes policiais.\nII. Uma das ideias apresentadas é que não há preconceito no país,\nem que o argumento para comprová-lo é que morrem mais\nnegros por serem maior percentual da população.\nIII. No contexto social brasileiro, a morte dos policiais ocorre por\nações provocadas por elementos externos a eles.\nAssinale\nA) se apenas as afirmativas I e II estiverem corretas.\nB) se apenas as afirmativas I e III estiverem corretas.\nC) se apenas as afirmativas II e III estiverem corretas.\nD) se todas as afirmativas estiverem corretas.\nE) se nenhuma afirmativa estiver correta.","item_number":2,"source_pages":[2],"answer_in_official_document":"A","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"primeiro_parecer_pedagogico_com_publicacao_retida","reviewed_at":"2026-10-23T00:16:25Z","publication_approved":false,"context_complete":true,"visual_checked":true,"answer_verified":false,"pedagogical_check_complete":true,"legal_review_applicability":"nao_juridica","question_format":"multiple_choice","observed_topic":"Inferência e atribuição de opiniões","observed_style":"Julgamento de afirmativas I/II/III","explanation":"I contrapõe menor circulação na pandemia ao crescimento de mortes. II reproduz a justificativa de ausência de preconceito atribuída ao policial entrevistado; trata-se de compreender a opinião citada, não de endossá-la. III é excessiva: o texto também menciona reações e crenças dos próprios policiais. A leitura é compatível com I e II, alternativa A, sem certificar o documento de Inspetor.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"title":"Gabarito PC-CE — seção do respectivo cargo, Tipo B","url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","page":3,"verified":true,"checked_at":"2026-10-23T00:16:25Z","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","scope":"Documento e divergência do cabeçalho conferidos; resposta definitiva NÃO certificada"}],"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[2],"checked_at":"2026-10-23T00:16:25Z","pdf_visual_checked":true},"restored_context":{"support_passage":{"title":"Policiais assassinados no Brasil são negros na maioria","source_page":2,"credit":"Anelise Gonçalves, Marcelo Azevedo, Matheus Rocha, Paulo Eduardo Dias, Paulo Ricardo Martins e Vitor Soares. Folha de S.Paulo, 1º ago.2021.","lines":[{"number":1,"text":"No ano passado, 194 policiais foram assassinados no país, e 63% deles eram negros."},{"number":2,"text":"Para Samira Bueno, diretora-executiva do Fórum Brasileiro de Segurança Pública, a ideia de que policiais são heróis os"},{"number":3,"text":"deixa mais vulneráveis e contribui para o aumento no número de mortes."},{"number":4,"text":"“Eles tendem a reagir a qualquer situação por causa da ideia fantasiosa de que se é policial 24 horas por dia.”"},{"number":5,"text":"Mesmo em um ano com menor circulação de pessoas nas ruas, devido à pandemia, a quantidade de mortes de agentes"},{"number":6,"text":"de segurança pública cresceu 13% no país em relação a 2019."},{"number":7,"text":"Segundo o último anuário do Fórum Brasileiro de Segurança Pública, 7 a cada 10 mortes ocorreram fora do horário de"},{"number":8,"text":"trabalho dos policiais. Eles foram mortos em passeios, no trajeto de ida e volta da corporação ou quando faziam serviços paralelos,"},{"number":9,"text":"os ‘‘bicos’’, ilegais, mas realizados para complementar a renda."},{"number":10,"text":"A reportagem ouviu um policial militar que atua no Rio de Janeiro há 20 anos."},{"number":11,"text":"“Entrei por querer estabilidade, depois me apaixonei pela profissão”, diz ele, que pediu para não ser identificado."},{"number":12,"text":"O PM criticou o treinamento dado pela corporação: ‘‘O policial acaba aprendendo na rua’’, diz. E reclamou da falta de"},{"number":13,"text":"apoio jurídico, do Estado, da sociedade e dos superiores ao trabalho do policial."},{"number":14,"text":"Sobre o fato de negros serem as maiores vítimas da violência, ele descarta preconceito. Na sua visão, ocorre porque a"},{"number":15,"text":"maioria da população é de pessoas negras. “Policial não escolhe criminoso.”"},{"number":16,"text":"Para a socióloga Paula Poncioni, pesquisadora da UFRJ (Universidade Federal do Rio de Janeiro), falhas de formação"},{"number":17,"text":"são um dos fatores que explicam o desempenho policial. “Muitas vezes, há um currículo ajustado à matriz nacional, mas não há"},{"number":18,"text":"professores qualificados, as aulas são recheadas de preconceitos”, diz a autora de “Tornar-se Policial’’ (Editora Appris)."},{"number":19,"text":"A letalidade policial, para Poncioni, decorre de uma sociedade “muito violenta e muito hierárquica”. Ela afirma que a"},{"number":20,"text":"polícia mata mais no Brasil por representar o pensamento geral da sociedade, refletido na composição dos governos que"},{"number":21,"text":"administram as polícias."},{"number":22,"text":"“A formação profissional está eivada de crenças, valores e preconceitos de um sistema de representação sobre o que é"},{"number":23,"text":"polícia, o que é criminoso, o que é mulher, o que é o menor e o que é o negro”, aponta."},{"number":24,"text":"O ouvidor da Polícia do Estado de São Paulo, Elizeu Soares Lopes, diz considerar a formação da polícia muito boa, mas"},{"number":25,"text":"ressalva que é preciso reforço. “Insistimos na necessidade de ações formativas em direitos humanos. A qualificação e a"},{"number":26,"text":"requalificação permanente dos quadros da polícia são fundamentais, seja ela civil, militar ou técnico-científica.”"},{"number":27,"text":"Hoje, a matriz curricular que define as regras para a formação de policiais no Brasil está em sua segunda versão, editada"},{"number":28,"text":"em 2014, no governo Dilma Rousseff (PT). Nela, o Ministério da Justiça orienta as ações formativas dos profissionais. Na grade"},{"number":29,"text":"dos cursos há, por exemplo, determinação para que os aspirantes tenham acesso a um módulo de 14 horas de aulas sobre"},{"number":30,"text":"diversidade étnico-racial."},{"number":31,"text":"Procurado, o Ministério da Justiça não respondeu."}],"historical_text":true},"reference_segments":[],"original_underline_segments":[],"typography_note":"Termos identificados visualmente na página; a extração original não foi reescrita.","original_exam_required_for_symbolic_notation":false}}}},{"candidate":"61b650f33b6d32c128683651afb32ccd2625a0653034fcbda34e0baabba92832","expected_status":"under_review","expected_payload":{"raw_text":"3. “Muitas vezes, há um currículo ajustado à matriz nacional, mas\nnão há professores qualificados, as aulas são recheadas de\npreconceitos”, diz a autora de “Tornar-se Policial’’ (Editora\nAppris). (linhas 17 e 18)\nAssinale a alternativa em que, alterando-se o segmento\nsublinhado no período acima, se tenha mantido correção\ngramatical, independentemente da mudança de sentido.\nA) não deve-se encontrar professores qualificados\nB) não hão de existir professores qualificados\nC) não poderão haver professores qualificados\nD) não deveria existir professores qualificados\nE) não deviam-se encontrar professores qualificados","item_number":3,"source_pages":[3],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"3. “Muitas vezes, há um currículo ajustado à matriz nacional, mas\nnão há professores qualificados, as aulas são recheadas de\npreconceitos”, diz a autora de “Tornar-se Policial’’ (Editora\nAppris). (linhas 17 e 18)\nAssinale a alternativa em que, alterando-se o segmento\nsublinhado no período acima, se tenha mantido correção\ngramatical, independentemente da mudança de sentido.\nA) não deve-se encontrar professores qualificados\nB) não hão de existir professores qualificados\nC) não poderão haver professores qualificados\nD) não deveria existir professores qualificados\nE) não deviam-se encontrar professores qualificados","item_number":3,"source_pages":[3],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente.","individual_review":{"review_stage":"primeiro_parecer_pedagogico_com_publicacao_retida","reviewed_at":"2026-10-23T00:16:25Z","publication_approved":false,"context_complete":true,"visual_checked":true,"answer_verified":false,"pedagogical_check_complete":true,"legal_review_applicability":"nao_juridica","question_format":"multiple_choice","observed_topic":"Concordância verbal e colocação pronominal","observed_style":"Reescrita com preservação de correção","explanation":"Em B, existir concorda com professores: não hão de existir professores qualificados. Nas locuções com haver existencial, o auxiliar fica no singular; com existir, a concordância é pessoal. A negativa também condiciona a colocação do pronome. A leitura é compatível com B; permanece a pendência documental do gabarito.","blockers":["vinculo_a_topico_de_edital_ativo_nao_conferido","cabecalho_preliminar_em_documento_listado_como_definitivo"],"primary_evidence":[{"title":"Gabarito PC-CE — seção do respectivo cargo, Tipo B","url":"https://antigo-concurso.idecan.org.br/ConcursoDownloadArquivo.aspx?ID2=1&ID=X6BT90RYGNDO2S8DGORM9OO61FDNBPF2P0I6D2GESRJNOE4S4WCY4LGHA0TVQ1S1DDEP85BIAPGOEYBF1384.pdf","page":3,"verified":true,"checked_at":"2026-10-23T00:16:25Z","sha256":"6bdc8686ea4c69b6651cf5b69e5f845a6e21589653bf0402b5776bcbdb748cb3","scope":"Documento e divergência do cabeçalho conferidos; resposta definitiva NÃO certificada"}],"booklet_evidence":{"url":"https://arquivos.qconcursos.com/prova/arquivo_prova/83735/idecan-2021-pc-ce-inspetor-de-policia-civil-prova.pdf","host_type":"mirror","sha256":"56a363de9d9c7d346d116c9e4d86cd8f5d737222ea51595a906c8596813c6cfe","source_pages":[3],"checked_at":"2026-10-23T00:16:25Z","pdf_visual_checked":true},"restored_context":{"support_passage":{"title":"Policiais assassinados no Brasil são negros na maioria","source_page":2,"credit":"Anelise Gonçalves, Marcelo Azevedo, Matheus Rocha, Paulo Eduardo Dias, Paulo Ricardo Martins e Vitor Soares. Folha de S.Paulo, 1º ago.2021.","lines":[{"number":1,"text":"No ano passado, 194 policiais foram assassinados no país, e 63% deles eram negros."},{"number":2,"text":"Para Samira Bueno, diretora-executiva do Fórum Brasileiro de Segurança Pública, a ideia de que policiais são heróis os"},{"number":3,"text":"deixa mais vulneráveis e contribui para o aumento no número de mortes."},{"number":4,"text":"“Eles tendem a reagir a qualquer situação por causa da ideia fantasiosa de que se é policial 24 horas por dia.”"},{"number":5,"text":"Mesmo em um ano com menor circulação de pessoas nas ruas, devido à pandemia, a quantidade de mortes de agentes"},{"number":6,"text":"de segurança pública cresceu 13% no país em relação a 2019."},{"number":7,"text":"Segundo o último anuário do Fórum Brasileiro de Segurança Pública, 7 a cada 10 mortes ocorreram fora do horário de"},{"number":8,"text":"trabalho dos policiais. Eles foram mortos em passeios, no trajeto de ida e volta da corporação ou quando faziam serviços paralelos,"},{"number":9,"text":"os ‘‘bicos’’, ilegais, mas realizados para complementar a renda."},{"number":10,"text":"A reportagem ouviu um policial militar que atua no Rio de Janeiro há 20 anos."},{"number":11,"text":"“Entrei por querer estabilidade, depois me apaixonei pela profissão”, diz ele, que pediu para não ser identificado."},{"number":12,"text":"O PM criticou o treinamento dado pela corporação: ‘‘O policial acaba aprendendo na rua’’, diz. E reclamou da falta de"},{"number":13,"text":"apoio jurídico, do Estado, da sociedade e dos superiores ao trabalho do policial."},{"number":14,"text":"Sobre o fato de negros serem as maiores vítimas da violência, ele descarta preconceito. Na sua visão, ocorre porque a"},{"number":15,"text":"maioria da população é de pessoas negras. “Policial não escolhe criminoso.”"},{"number":16,"text":"Para a socióloga Paula Poncioni, pesquisadora da UFRJ (Universidade Federal do Rio de Janeiro), falhas de formação"},{"number":17,"text":"são um dos fatores que explicam o desempenho policial. “Muitas vezes, há um currículo ajustado à matriz nacional, mas não há"},{"number":18,"text":"professores qualificados, as aulas são recheadas de preconceitos”, diz a autora de “Tornar-se Policial’’ (Editora Appris)."},{"number":19,"text":"A letalidade policial, para Poncioni, decorre de uma sociedade “muito violenta e muito hierárquica”. Ela afirma que a"},{"number":20,"text":"polícia mata mais no Brasil por representar o pensamento geral da sociedade, refletido na composição dos governos que"},{"number":21,"text":"administram as polícias."},{"number":22,"text":"“A formação profissional está eivada de crenças, valores e preconceitos de um sistema de representação sobre o que é"},{"number":23,"text":"polícia, o que é criminoso, o que é mulher, o que é o menor e o que é o negro”, aponta."},{"number":24,"text":"O ouvidor da Polícia do Estado de São Paulo, Elizeu Soares Lopes, diz considerar a formação da polícia muito boa, mas"},{"number":25,"text":"ressalva que é preciso reforço. “Insistimos na necessidade de ações formativas em direitos humanos. A qualificação e a"},{"number":26,"text":"requalificação permanente dos quadros da polícia são fundamentais, seja ela civil, militar ou técnico-científica.”"},{"number":27,"text":"Hoje, a matriz curricular que define as regras para a formação de policiais no Brasil está em sua segunda versão, editada"},{"number":28,"text":"em 2014, no governo Dilma Rousseff (PT). Nela, o Ministério da Justiça orienta as ações formativas dos profissionais. Na grade"},{"number":29,"text":"dos cursos há, por exemplo, determinação para que os aspirantes tenham acesso a um módulo de 14 horas de aulas sobre"},{"number":30,"text":"diversidade étnico-racial."},{"number":31,"text":"Procurado, o Ministério da Justiça não respondeu."}],"historical_text":true},"reference_segments":["não há professores qualificados"],"original_underline_segments":["não há professores qualificados"],"typography_note":"Termos identificados visualmente na página; a extração original não foi reescrita.","original_exam_required_for_symbolic_notation":false}}}},{"candidate":"5958f4b075a4c34ab00fd36eacad4d5f3070000b62e10f70c7d27d0b45010750","expected_status":"under_review","expected_payload":{"raw_text":"4. No ano passado, 194 policiais foram assassinados no país, e\n63% deles eram negros. (linha 1)\nAssinale a alternativa em que, alterando-se o segmento\nsublinhado no período acima, NÃO se tenha mantido correção\ngramatical. Não leve em conta as alterações de sentido.\nA) e 0,98% deles se dizia negro\nB) e 1,89% da população se diziam negros\nC) e um quinto se dizia negro\nD) e 42% da população se dizia negra\nE) e dois sétimos deles se diziam negros","item_number":4,"source_pages":[3],"answer_in_official_document":"B","answer_key_requires_clarification":true,"annulled_in_document":false,"alternative_labels_extracted":["A","B","C","D","E"],"context_review_required":true,"visual_review_required":true,"legal_review_required":false,"syllabus_mapping_required":true,"local_legislation_review_required":false,"review_note":"Extração bruta: conferir texto de apoio, destaques, figuras, alternativas e vigência no PDF. Não publicar automaticamente."},"next_status":"reviewed","next_payload":{"raw_text":"4. No ano passado, 194 policiais foram assassinados no país, e\n63% deles eram negros. (linha 1)\nAssinale a alternativa em que, alterando-se o segmento\nsublinhado no período acima, NÃO se tenha mantido correção\ngramatical. Não leve em conta as alterações de sentido.\nA) e 0,98% deles se dizia negro\nB) e 1,89% da população se diziam negros\nC) e um quinto se dizia negro\nD) e 42% da população se dizia negra\nE) e dois sétimos deles se diziam negros","item_number":4,"source_pages":[3],"answer_in_official_document":"B","answer_key_requi